const $=s=>document.querySelector(s),opt=(items,value,empty)=> (empty!==undefined?`<option value="">${e(empty)}</option>`:'')+items.map(x=>`<option value="${e(x.id)}" ${String(value)===String(x.id)?'selected':''}>${e(x.name)}</option>`).join('');
const input=(name,label,value='',type='text',attr='')=>`<label class="form-field">${e(label)}<input name="${name}" type="${type}" value="${e(value??'')}" ${attr}></label>`;
const select=(name,label,items,value,empty)=>`<label class="form-field">${e(label)}<select name="${name}">${opt(items,value,empty)}</select></label>`;
const table=(headers,rows)=>`<div class="studio-table"><table><thead><tr>${headers.map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Sem registos.</td></tr>`}</tbody></table></div>`;
const api=async(path,options={})=>{const res=await fetch(path,options);const data=await res.json();if(!res.ok)throw new Error(data.error||'Operação indisponível.');return data;};
