 const roomsUI=initRoomWorkspace(app,{form,input,select,scope:()=>({floorId:floor,roomId:room}),openRoom,openFloor,connect:simpleNetwork.open,cableForm,roomForm,showRoute(result){floor='';room='';selectedLink='';routeEditing=false;app.showRoute(result);}});
 const mapTools=initMapTools(app,{form,openFloor,openRoom,scope:()=>({floorId:floor,roomId:room})});
 function openFloor(id){app.clearMapRoute();floor=id;room='';selectedLink='';routeEditing=false;app.setMode('plan');loadFloorImage().catch(err=>message(err.message,true));}
 function openRoom(id){if(app.get().mode==='physical'){app.select('rooms',id);return;}const r=app.get().project.rooms.find(r=>r.id===id);if(!r)return;app.clearMapRoute();floor=r.floor;room=id;selectedLink='';routeEditing=false;app.setMode('plan');}
 const openCabling=initCablingAssistant(app,result=>{floor='';room='';selectedLink='';routeEditing=false;$('#studio').close();app.showCabling(result);});
 function message(text,error=false){$('#studioStatus').textContent=text;$('#studioStatus').classList.toggle('error',error);}
 function act(fn){try{return fn();}catch(err){message(err.message,true);app.status(err.message,true);}}
 function form(title,fields,onSubmit,setup){if(!mayDiscard($('#featureDialog')))return;$('#featureTitle').textContent=title;$('#featureFields').innerHTML=fields;$('#featureError').textContent='';const f=$('#featureForm');f.querySelectorAll('#connectionBack,#connectionNext').forEach(b=>b.remove());const submit=f.querySelector('[type=submit]');submit.hidden=false;submit.disabled=false;submit.textContent='Guardar alterações';f.onsubmit=async ev=>{ev.preventDefault();const button=f.querySelector('[type=submit]'),originalLabel=button.textContent;button.disabled=true;button.textContent='A guardar…';f.setAttribute('aria-busy','true');try{const values={};for(const el of f.elements){if(!el.name||el.disabled)continue;values[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?null:Number(el.value)):el.value.trim();}await onSubmit(values,f);$('#featureDialog').close();if($('#studio').open)renderTab();}catch(err){$('#featureError').textContent=err.message;fieldError(f,err);}finally{button.disabled=false;button.textContent=originalLabel;f.removeAttribute('aria-busy');}};setup?.(f);beginForm($('#featureDialog'));if(!$('#featureDialog').open)$('#featureDialog').showModal();}
 function open(value){tab=value;$('#studioTitle').textContent=tabs[tab];$('#studioTabs').querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.hidden=!toolGroup(tab).includes(b.dataset.tab);});message('');renderTab();if(!$('#studio').open)$('#studio').showModal();if(tab==='versions')loadVersions();}
 function renderTab(){if(tab==='examples')renderExamples();if(tab==='cables')renderCables();if(tab==='spaces')renderSpaces();if(tab==='mount')renderMount();if(tab==='power')renderPower();if(tab==='templates')renderTemplates();if(tab==='audit')renderAudit();if(tab==='simulation')renderSimulation();if(tab==='versions')renderVersions();if(tab==='dossier')renderDossier();}
 function renderExamples(){const current=app.get().project;$('#studioBody').innerHTML='<p class="notice">Cenários fictícios e editáveis. Ao abrir um exemplo, o projeto atual é guardado em Versões antes da substituição.</p><div class="example-grid">'+exampleCatalog.map(ex=>{const p=makeExample(ex.id);return `<article class="example-card"><h3>${e(ex.title)}</h3><p>${e(ex.description)}</p><div class="example-count">${p.floors.length} pisos · ${p.racks.length} bastidores · ${p.devices.length} equipamentos</div><ol>${ex.steps.map(step=>`<li>${e(step)}</li>`).join('')}</ol><button class="primary" data-load-example="${ex.id}">Abrir exemplo</button><button data-download-example="${ex.id}">Descarregar projeto JSON</button></article>`;}).join('')+'</div>';
 $('#studioBody').querySelectorAll('[data-download-example]').forEach(b=>b.onclick=()=>downloadFile(new Blob([JSON.stringify(makeExample(b.dataset.downloadExample),null,2)],{type:'application/json'}),'atlas-exemplo-'+b.dataset.downloadExample+'.json'));
 $('#studioBody').querySelectorAll('[data-load-example]').forEach(b=>b.onclick=async()=>{if(!app.get().ready)return message('Aguarde o carregamento do projeto.',true);b.disabled=true;try{message('A guardar o projeto atual em Versões…');const p=makeExample(b.dataset.loadExample);await post('/api/versions',{label:('Antes do exemplo · '+current.name).slice(0,100),project:app.get().project});floor=exampleCatalog.find(ex=>ex.id===p.exampleKey)?.initialFloor||'';room='';selectedLink='';sourcePort=null;disabledDevices=[];disabledLinks=[];simulation=null;routeEditing=false;planImages['atlas-example-floor']=sampleFloorImage;app.replace(p);app.select('sites',p.sites[0].id);app.setMode(exampleCatalog.find(ex=>ex.id===p.exampleKey)?.initialView||'physical');$('#studio').close();app.status('Exemplo aberto. O projeto anterior está disponível em Versões.');}catch(err){message(err.message,true);}finally{b.disabled=false;}});
 }
 function renderCables(){const p=app.get().project,devices=new Map(p.devices.map(d=>[d.id,d])),kindNames={copper:'Ethernet',fiber:'Fibra ótica',virtual:'Virtual / Wi-Fi',power:'Alimentação'};const location=l=>{const a=devices.get(l.a),b=devices.get(l.b);return a.site===b.site?(p.sites.find(s=>s.id===a.site)?.name||'Sem edifício'):'Entre edifícios';};
 $('#studioBody').innerHTML=`<div class="studio-intro"><p>Escolha «Ligar dois equipamentos» para um cabo direto. Para passar por uma tomada e um patch panel, escolha «Ligar um posto ao bastidor».</p><button id="cablingAssistant" class="primary">Ligar um posto ao bastidor</button><button id="newCable">Ligar dois equipamentos</button></div><div class="cable-filters"><label>Pesquisar<input id="cableSearch" type="search" placeholder="Cabo, equipamento, IP ou porta…"></label><label>Edifício<select id="cableSite">${opt(p.sites,'','Todos')}</select></label><label>Tipo<select id="cableKind">${opt(Object.entries(kindNames).map(([id,name])=>({id,name})),'','Todos')}</select></label><button id="clearCableFilters">Limpar</button></div><p id="cableCount" role="status"></p><div id="cableGroups"></div>`;
 const draw=()=>{const q=$('#cableSearch').value.toLowerCase(),site=$('#cableSite').value,kind=$('#cableKind').value,links=p.links.filter(l=>{const a=devices.get(l.a),b=devices.get(l.b);return(!kind||l.kind===kind)&&(!site||a.site===site||b.site===site)&&(!q||[l.label,l.portA,l.portB,a.name,b.name,a.ip,b.ip].join(' ').toLowerCase().includes(q));});$('#cableCount').textContent=links.length+' de '+p.links.length+' ligações';const groups=new Map();for(const l of links){const key=location(l);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(l);}$('#cableGroups').innerHTML=links.length?[...groups].sort(([a],[b])=>a.localeCompare(b,'pt')).map(([name,list])=>'<details class="cable-group" open><summary>'+e(name)+' <span>'+list.length+' ligações</span></summary>'+table(['Cabo','Origem → destino','Tipo','Ações'],list.sort((a,b)=>(a.label||a.id).localeCompare(b.label||b.id,'pt',{numeric:true})).map(l=>[`<span class="cable-dot" style="background:${l.color}"></span><b>${e(l.label||l.id)}</b><small>${l.length===null?'':e(l.length+' m')}</small>`,`<b>${e(devices.get(l.a)?.name)}</b><small>${e(l.portA||'Virtual')} → ${e(l.portB||'Virtual')}</small><b>${e(devices.get(l.b)?.name)}</b>`,e(kindNames[l.kind]),`<button data-highlight="${l.id}">Destacar</button><button data-cable="${l.id}">Editar</button><details class="cable-more"><summary>Mais</summary><button data-route="${l.id}">Desenhar percurso</button><button data-delete-cable="${l.id}" class="danger">Eliminar</button></details>`]))+'</details>').join(''):'<div class="cable-empty">Nenhuma ligação corresponde à pesquisa. Altere os filtros ou crie uma nova ligação.</div>';
 $('#cableGroups').querySelectorAll('[data-cable]').forEach(b=>b.onclick=()=>cableForm(b.dataset.cable));$('#cableGroups').querySelectorAll('[data-highlight]').forEach(b=>b.onclick=()=>{selectedLink=b.dataset.highlight;floor='';room='';const l=p.links.find(l=>l.id===selectedLink);app.highlight({devices:[l.a,l.b],links:[l.id]});app.setMode('physical');$('#studio').close();});$('#cableGroups').querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{selectedLink=b.dataset.route;routeEditing=true;$('#studio').close();app.setMode('plan');});$('#cableGroups').querySelectorAll('[data-delete-cable]').forEach(b=>b.onclick=()=>{if(confirm('Eliminar este cabo?'))act(()=>{app.mutate(p=>p.links=p.links.filter(l=>l.id!==b.dataset.deleteCable));renderCables();});});};
 $('#cablingAssistant').onclick=openCabling;$('#newCable').onclick=()=>act(()=>cableForm(null,app.get().selected.type==='devices'?{a:app.get().selected.id,b:p.devices.find(d=>d.id!==app.get().selected.id)?.id}:{}));$('#cableSearch').oninput=draw;$('#cableSite').onchange=$('#cableKind').onchange=draw;$('#clearCableFilters').onclick=()=>{$('#cableSearch').value='';$('#cableSite').value='';$('#cableKind').value='';draw();};draw();}
 function outletForm(pduId,port){const p=app.get().project,pdu=p.devices.find(d=>d.id===pduId),targets=p.devices.filter(d=>d.id!==pduId&&powerInputs(p,d).some(input=>!portInUse(p,d.id,input))).sort((a,b)=>Number(b.rack===pdu.rack)-Number(a.rack===pdu.rack)||a.name.localeCompare(b.name));if(!targets.length)return app.status('Não há entradas de alimentação livres nos equipamentos.',true);form('Ligar '+pdu.name+' · tomada '+port.slice(3).padStart(2,'0'),'<p class="wide notice">A tomada fica associada ao equipamento e à respetiva fonte de alimentação.</p>'+select('deviceId','Equipamento',targets.map(d=>({...d,name:d.name+' · '+(p.racks.find(r=>r.id===d.rack)?.name||'Fora do bastidor')})),targets[0].id)+select('input','Entrada de alimentação',[],''),v=>{app.mutate(p=>connectOutlet(p,pduId,port,v.deviceId,v.input));app.status('Alimentação identificada e guardada.');},f=>{const refresh=()=>{const d=p.devices.find(d=>d.id===f.elements.deviceId.value);f.elements.input.innerHTML=opt(powerInputs(p,d).filter(port=>!portInUse(p,d.id,port)).map(id=>({id,name:id})),null);};f.elements.deviceId.onchange=refresh;refresh();});}
 function renderPower(){const p=app.get().project,pdus=p.devices.filter(d=>d.type==='PDU');$('#studioBody').innerHTML='<div class="studio-intro"><p>Réguas de alimentação com tomadas numeradas. Cada saída identifica o equipamento, a fonte e o cabo associado.</p><button id="addPdu" class="primary">+ Régua PDU</button></div>'+ (pdus.length?pdus.map(d=>{const outlets=pduOutlets(p,d),used=outlets.filter(o=>o.link).length,feed=portInUse(p,d.id,'IN'),source=feed?p.devices.find(x=>x.id===(feed.a===d.id?feed.b:feed.a)):null;return `<section class="pdu-card"><div class="pdu-head"><div><h3>${e(d.name)}</h3><p>${e(p.racks.find(r=>r.id===d.rack)?.name||'Fora do bastidor')} · ${used}/${outlets.length} tomadas ligadas</p><p>Entrada: ${e(source?.name||d.specs?.feed||'Por identificar')}</p></div><div><button data-edit-pdu="${d.id}">Configurar régua</button><button data-label-pdu="${d.id}">Identificar tomadas</button>${d.rack?`<button data-view-pdu="${d.id}">Ver traseira 3D</button>`:''}</div></div><div class="pdu-strip">${outlets.map(o=>`<button class="pdu-outlet ${o.link?'occupied':''}" data-pdu="${d.id}" data-outlet="${o.port}" title="${e(o.device?o.device.name+' / '+o.input:'Ligar equipamento')}"><span class="socket-icon" aria-hidden="true">∴</span><b>${o.number}</b><span>${e(o.label||'Tomada '+o.number)}</span><strong>${e(o.device?.name||'Livre')}</strong><small>${e(o.input||'Selecionar equipamento')}</small></button>`).join('')}</div>`+table(['Tomada / identificação','Equipamento','Fonte','Cabo','Ações'],outlets.filter(o=>o.link).map(o=>[e(o.number+(o.label?' · '+o.label:'')),e(o.device?.name),e(o.input),e(o.link.label),`<button data-power-link="${o.link.id}">Editar ligação</button><button data-power-focus="${o.link.id}">Seguir cabo</button><button data-power-remove="${o.link.id}">Desligar no modelo</button>`]))+'</section>';}).join(''):'<p class="cable-empty">Ainda não existem réguas. Crie uma PDU e escolha o bastidor onde a pretende instalar.</p>');
 $('#addPdu').onclick=()=>{const rack=p.racks.find(r=>r.id===app.get().activeRack)||p.racks[0];$('#studio').close();app.edit('devices',null,{type:'PDU',rack:rack?.id||'',site:rack?.site});};$('#studioBody').querySelectorAll('[data-edit-pdu]').forEach(b=>b.onclick=()=>{$('#studio').close();app.edit('devices',b.dataset.editPdu);});$('#studioBody').querySelectorAll('[data-view-pdu]').forEach(b=>b.onclick=()=>{floor='';room='';face='rear';$('#studio').close();app.select('devices',b.dataset.viewPdu);app.setMode('rack');});
 $('#studioBody').querySelectorAll('[data-label-pdu]').forEach(b=>b.onclick=()=>{const d=p.devices.find(d=>d.id===b.dataset.labelPdu);form('Identificar tomadas · '+d.name,pduOutlets(p,d).map(o=>input('outlet_'+o.number,'Tomada '+o.number,o.label,'text','maxlength="80" placeholder="Ex.: Servidor principal · fonte A"')).join(''),v=>app.mutate(p=>{const d=p.devices.find(d=>d.id===b.dataset.labelPdu);d.outletLabels={};for(const [k,value] of Object.entries(v))if(value)d.outletLabels['OUT'+Number(k.slice(7))]=value;}));});
 $('#studioBody').querySelectorAll('[data-outlet]').forEach(b=>b.onclick=()=>{const cable=portInUse(p,b.dataset.pdu,b.dataset.outlet);if(cable)cableForm(cable.id);else outletForm(b.dataset.pdu,b.dataset.outlet);});$('#studioBody').querySelectorAll('[data-power-link]').forEach(b=>b.onclick=()=>cableForm(b.dataset.powerLink));$('#studioBody').querySelectorAll('[data-power-focus]').forEach(b=>b.onclick=()=>{const l=p.links.find(l=>l.id===b.dataset.powerFocus),d=p.devices.find(d=>d.id===l.a),other=p.devices.find(d=>d.id===l.b);floor='';room='';face='rear';app.select('devices',d.id);app.setMode(d.rack&&d.rack===other.rack?'rack':'physical');selectedLink=l.id;app.highlight({devices:[l.a,l.b],links:[l.id]});$('#studio').close();});$('#studioBody').querySelectorAll('[data-power-remove]').forEach(b=>b.onclick=()=>{if(confirm('Retirar apenas esta ligação elétrica do modelo?'))act(()=>{app.mutate(p=>p.links=p.links.filter(l=>l.id!==b.dataset.powerRemove));renderPower();});});}
 function renderSpaces(){const p=app.get().project;$('#studioBody').innerHTML=`<div class="studio-intro"><p>Organize os edifícios por pisos e salas. Atribua equipamentos e bastidores a cada sala, e selecione um piso para ver a planta de fundo.</p><div><button id="newBuilding" class="primary">+ Edifício com pisos e salas</button><button id="newFloor">+ Piso</button><button id="newRoom">+ Sala</button></div></div>`+table(['Piso','Edifício','Cota','Planta','Ações'],p.floors.map(f=>[e(f.name),e(p.sites.find(s=>s.id===f.site)?.name),e(f.elevation+' m'),f.plan?e(f.plan.widthMeters.toFixed(2)+' × '+f.plan.heightMeters.toFixed(2)+' m'):'Sem imagem',`<button data-view-floor="${f.id}">Ver</button><button data-floor="${f.id}">Editar</button><button data-upload="${f.id}">Importar planta</button>${f.plan?`<button data-calibrate="${f.id}">Calibrar</button><button data-clear-plan="${f.id}">Remover imagem</button>`:''}<button data-delete-floor="${f.id}" class="danger">Eliminar</button>`]))+'<h3>Salas</h3>'+table(['Sala','Piso','Dimensões','Ações'],p.rooms.map(r=>[e(r.name),e(p.floors.find(f=>f.id===r.floor)?.name),e(r.w+' × '+r.d+' m'),`<button data-enter-room="${r.id}">Abrir sala</button><button data-room="${r.id}">Editar</button><button data-delete-room="${r.id}">Eliminar</button>`]));
 $('#studioBody').querySelectorAll('[data-enter-room]').forEach(b=>b.onclick=()=>{$('#studio').close();openRoom(b.dataset.enterRoom);});$('#newBuilding').onclick=createBuilding;$('#newFloor').onclick=()=>floorForm();$('#newRoom').onclick=()=>roomForm();$('#studioBody').querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>floorForm(b.dataset.floor));$('#studioBody').querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>roomForm(b.dataset.room));$('#studioBody').querySelectorAll('[data-view-floor]').forEach(b=>b.onclick=()=>{floor=b.dataset.viewFloor;room='';$('#studio').close();app.setMode('plan');loadFloorImage();});$('#studioBody').querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>uploadPlan(b.dataset.upload));$('#studioBody').querySelectorAll('[data-calibrate]').forEach(b=>b.onclick=()=>calibratePlan(b.dataset.calibrate));$('#studioBody').querySelectorAll('[data-clear-plan]').forEach(b=>b.onclick=()=>{if(confirm('Remover a imagem de fundo deste piso?'))act(()=>{app.mutate(p=>delete p.floors.find(f=>f.id===b.dataset.clearPlan).plan);renderSpaces();});});$('#studioBody').querySelectorAll('[data-delete-room]').forEach(b=>b.onclick=()=>{if(confirm('Eliminar a sala? Os equipamentos ficam no mesmo piso, sem sala.'))act(()=>{app.mutate(p=>{p.rooms=p.rooms.filter(r=>r.id!==b.dataset.deleteRoom);for(const d of [...p.devices,...p.racks])if(d.room===b.dataset.deleteRoom)d.room='';});renderSpaces();});});$('#studioBody').querySelectorAll('[data-delete-floor]').forEach(b=>b.onclick=()=>act(()=>{const id=b.dataset.deleteFloor;if([...p.devices,...p.racks].some(d=>d.floor===id)||p.rooms.some(r=>r.floor===id))throw new Error('Transfira as salas, bastidores e equipamentos antes de eliminar o piso.');if(p.floors.filter(f=>f.site===p.floors.find(f=>f.id===id).site).length===1)throw new Error('O edifício deve manter pelo menos um piso.');if(confirm('Eliminar este piso?')){app.mutate(p=>p.floors=p.floors.filter(f=>f.id!==id));renderSpaces();}}));}
 function floorForm(id){const p=app.get().project;if(!p.sites.length)return message('Crie primeiro um edifício.',true);const f=p.floors.find(f=>f.id===id)||{name:'Novo piso',site:p.sites[0].id,level:1,elevation:3};form(id?'Editar piso':'Criar piso',input('name','Nome',f.name,'text','required')+select('site','Edifício',p.sites,f.site)+input('level','Número / nível',f.level,'number','min="-10" max="150" required')+input('elevation','Cota no modelo (m)',f.elevation,'number','min="-50" max="500" step="0.1" required'),v=>app.mutate(p=>{if(id){if(v.site!==f.site&&([...p.devices,...p.racks].some(d=>d.floor===id)||p.rooms.some(r=>r.floor===id)))throw new Error('Um piso com elementos não pode mudar de edifício.');Object.assign(p.floors.find(f=>f.id===id),v);}else p.floors.push({...v,id:uid('floor')});}));}
 function roomForm(id){const p=app.get().project;if(!p.floors.length)return message('Crie primeiro um piso.',true);const r=p.rooms.find(r=>r.id===id)||{name:'Nova sala',floor:floor||p.floors[0].id,x:0,z:0,w:4,d:3};form(id?'Editar sala':'Criar sala',input('name','Nome da sala',r.name,'text','required')+select('floor','Piso',p.floors.map(f=>({...f,name:p.sites.find(s=>s.id===f.site)?.name+' · '+f.name})),r.floor)+'<details class="wide room-geometry"><summary>Medidas e posição na planta (opcional)</summary><p class="notice">Pode começar com as medidas sugeridas e ajustar a planta depois.</p><div class="form-grid">'+input('x','Centro X, relativo ao edifício',r.x,'number','step="0.1" required')+input('z','Centro Z, relativo ao edifício',r.z,'number','step="0.1" required')+input('w','Largura (m)',r.w,'number','min="0.1" step="0.1" required')+input('d','Profundidade (m)',r.d,'number','min="0.1" step="0.1" required')+'</div></details>',v=>{const newId=id||uid('room');if(app.mutate(p=>{if(id){if(v.floor!==r.floor&&[...p.devices,...p.racks].some(d=>d.room===id))throw new Error('Retire os elementos da sala antes de a transferir de piso.');Object.assign(p.rooms.find(r=>r.id===id),v);}else p.rooms.push({...v,id:newId});},id?'configurar sala '+v.name:'criar sala '+v.name)&&!id){$('#studio').close();openRoom(newId);}});}

 function assignLocation(type,id){const p=app.get().project,d=p[type].find(x=>x.id===id);if(!d)return;const floors=p.floors.filter(f=>f.site===d.site);form('Piso e sala de '+d.name,select('floor','Piso',floors,d.floor)+select('room','Sala',p.rooms.filter(r=>r.floor===d.floor),d.room,'Sem sala'),v=>app.mutate(p=>{const item=p[type].find(x=>x.id===id);if(type==='devices'&&(item.rack||item.type==='VM'))throw new Error('Altere a localização do bastidor ou do servidor anfitrião.');Object.assign(item,v);if(type==='racks')for(const device of p.devices.filter(d=>d.rack===id)){Object.assign(device,v);for(const vm of p.devices.filter(d=>d.host===device.id))Object.assign(vm,v);}}),f=>{f.elements.floor.onchange=()=>f.elements.room.innerHTML=opt(p.rooms.filter(r=>r.floor===f.elements.floor.value),'','Sem sala');});}
 async function loadFloorImage(){const f=app.get().project.floors.find(f=>f.id===floor);if(!f?.plan)return;await imageData(f.plan.asset);app.render();}
 async function imageData(id){if(id==='atlas-example-floor'){planImages[id]=sampleFloorImage;return sampleFloorImage;}if(planImages[id])return planImages[id];if(busyImages.has(id))return busyImages.get(id);const pending=(async()=>{try{const response=await fetch('/api/assets/'+id);if(!response.ok)throw new Error('Não foi possível carregar a imagem da planta.');const blob=await response.blob();planImages[id]=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});return planImages[id];}catch(err){app.status(err.message,true);return null;}finally{busyImages.delete(id);}})();busyImages.set(id,pending);return pending;}

 function uploadPlan(floorId){const p=app.get().project,floorObj=p.floors.find(f=>f.id===floorId),site=p.sites.find(s=>s.id===floorObj.site);form('Importar planta · '+floorObj.name,`<label class="form-field wide">Imagem da planta (PNG, JPEG ou WebP; até 5 MB)<input id="planUploadFile" type="file" accept="image/png,image/jpeg,image/webp" required></label>`+input('widthMeters','Largura real representada (m)',site.w,'number','min="0.1" max="1000" step="0.01" required')+input('x','Centro X relativo ao edifício',0,'number','step="0.1" required')+input('z','Centro Z relativo ao edifício',0,'number','step="0.1" required')+input('opacity','Opacidade (0 a 1)',.65,'number','min="0" max="1" step="0.05" required')+'<p class="wide notice">Pode calibrar a escala com dois pontos e uma distância conhecida depois de importar.</p>',async v=>{const file=$('#planUploadFile').files[0];if(!file||file.size>5000000)throw new Error('Escolha uma imagem com até 5 MB.');const image=await createImageBitmap(file);if(image.width>12000||image.height>12000){image.close();throw new Error('A imagem excede 12000 píxeis de lado.');}const ratio=image.height/image.width;const canvas=document.createElement('canvas');const factor=Math.min(1,2400/image.width,2400/image.height);canvas.width=Math.round(image.width*factor);canvas.height=Math.round(image.height*factor);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob||blob.size>5000000)throw new Error('A imagem convertida é demasiado grande. Use uma resolução menor.');const res=await api('/api/assets',{method:'POST',headers:{'Content-Type':'image/png'},body:blob});app.mutate(p=>p.floors.find(f=>f.id===floorId).plan={asset:res.id,widthMeters:v.widthMeters,heightMeters:v.widthMeters*ratio,x:v.x,z:v.z,opacity:v.opacity});floor=floorId;await imageData(res.id);app.render();});}
 async function calibratePlan(id){const f=app.get().project.floors.find(f=>f.id===id);const src=await imageData(f.plan.asset);if(!src)return;let points=[];form('Calibrar planta · '+f.name,`<p class="wide notice">Clique em dois pontos na imagem. Indique a distância real entre eles.</p><div id="calibration" class="wide"><img src="${src}" alt="Planta para calibração"><svg viewBox="0 0 100 100" preserveAspectRatio="none"></svg></div><p class="wide" id="calibrationStatus">Selecione o primeiro ponto.</p>`+input('distance','Distância entre os pontos (m)',1,'number','min="0.01" step="0.01" required')+input('opacity','Opacidade',f.plan.opacity,'number','min="0" max="1" step="0.05" required'),v=>{if(points.length!==2)throw new Error('Selecione dois pontos na imagem.');const image=$('#calibration img'),ratio=image.naturalHeight/image.naturalWidth;const span=Math.hypot(points[1].x-points[0].x,(points[1].y-points[0].y)*ratio);if(span<.001)throw new Error('Os pontos estão demasiado próximos.');app.mutate(p=>{const plan=p.floors.find(f=>f.id===id).plan;plan.widthMeters=v.distance/span;plan.heightMeters=plan.widthMeters*ratio;plan.opacity=v.opacity;});},()=>{$('#calibration').onclick=ev=>{const r=$('#calibration img').getBoundingClientRect();const x=(ev.clientX-r.left)/r.width,y=(ev.clientY-r.top)/r.height;if(x<0||x>1||y<0||y>1)return;if(points.length===2)points=[];points.push({x,y});$('#calibration svg').innerHTML=points.map(p=>`<circle cx="${p.x*100}" cy="${p.y*100}" r="1" fill="#eb634d"/>`).join('')+(points.length===2?`<line x1="${points[0].x*100}" y1="${points[0].y*100}" x2="${points[1].x*100}" y2="${points[1].y*100}" stroke="#eb634d" stroke-width=".4"/>`:'');$('#calibrationStatus').textContent=points.length===2?'Dois pontos selecionados. Indique a distância e guarde.':'Selecione o segundo ponto.';};});}
 function renderMount(){const p=app.get().project;if(!rackTargets.length)rackTargets=p.racks.slice(0,2).map(r=>r.id);rackTargets=rackTargets.filter(id=>p.racks.some(r=>r.id===id));$('#studioBody').innerHTML=`<div class="studio-intro"><p>Arraste um equipamento para a unidade U inicial pretendida. Pode movê-lo entre os dois bastidores. Os espaços ocupados são validados antes de guardar.</p></div><div class="mount-pickers">${[0,1].map(i=>`<label>Bastidor ${i+1}<select data-mount-rack="${i}">${opt(p.racks,rackTargets[i]||'','Escolher bastidor')}</select></label>`).join('')}</div><div class="mount-grid">${rackTargets.map(id=>rackBoard(p,id)).join('')}</div><h3>Equipamentos fora dos bastidores</h3><div id="unmounted">${p.devices.filter(d=>!d.rack&&d.type!=='VM').map(d=>`<button draggable="true" data-drag-device="${d.id}">${e(d.name)} · ${d.units||1} U</button>`).join('')||'<p class="notice">Não existem equipamentos livres.</p>'}</div><p class="notice">Alternativa ao arrasto: selecione um equipamento e use «Instalar / transferir».</p><select id="mountDevice">${opt(p.devices.filter(d=>d.type!=='VM'),app.get().selected?.id)}</select><button id="mountByForm">Instalar / transferir</button>`;$('#studioBody').querySelectorAll('[data-mount-rack]').forEach(s=>s.onchange=()=>{rackTargets[+s.dataset.mountRack]=s.value;rackTargets=[...new Set(rackTargets.filter(Boolean))];renderMount();});$('#studioBody').querySelectorAll('[data-drag-device]').forEach(el=>el.ondragstart=ev=>{ev.dataTransfer.setData('text/plain',el.dataset.dragDevice);ev.dataTransfer.effectAllowed='move';});$('#studioBody').querySelectorAll('[data-slot]').forEach(el=>{el.ondragover=ev=>{ev.preventDefault();el.classList.add('drop-target');};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=ev=>{ev.preventDefault();el.classList.remove('drop-target');const id=ev.dataTransfer.getData('text/plain');act(()=>{app.mutate(p=>placeEquipment(p,id,el.dataset.rack,Number(el.dataset.slot)));renderMount();message('Equipamento instalado.');});};});$('#mountByForm').onclick=()=>mountForm($('#mountDevice').value);}
 function rackBoard(p,id){const r=p.racks.find(r=>r.id===id);if(!r)return '';let rows='';for(let u=r.units;u>=1;u--){const d=p.devices.find(d=>d.rack===r.id&&u>=d.u&&u<d.u+d.units);rows+=`<div class="rack-slot ${d?'occupied':''}" data-slot="${u}" data-rack="${r.id}"><span>U${u}</span>${d?`<button draggable="true" data-drag-device="${d.id}" title="${e(d.name)}">${u===d.u+d.units-1?e(d.name)+' · '+d.units+' U':'↳ '+e(d.name)}</button>`:'<small>Livre</small>'}</div>`;}return `<section class="rack-board"><h3>${e(r.name)}<small>${e(p.sites.find(s=>s.id===r.site)?.name)}</small></h3>${rows}</section>`;}
 function mountForm(id){const p=app.get().project,d=p.devices.find(d=>d.id===id);if(!d||!p.racks.length)return message('Crie um bastidor e um equipamento.',true);form('Instalar '+d.name,select('rack','Bastidor',p.racks,d.rack||p.racks[0].id)+input('u','Unidade U inicial',d.u||1,'number','min="1" max="60" required'),v=>app.mutate(p=>placeEquipment(p,id,v.rack,v.u)));}
 function renderTemplates(){const p=app.get().project;$('#studioBody').innerHTML=`<div class="studio-intro"><p>Guarde um edifício ou bastidor como modelo. As cópias incluem os equipamentos e ligações internas; os endereços IP ficam vazios para evitar duplicados.</p><button id="newTemplate">+ Guardar modelo</button></div>`+table(['Modelo','Tipo','Conteúdo','Ações'],p.templates.map(t=>[e(t.name),t.type==='sites'?'Edifício':'Bastidor',e(t.blueprint.racks.length+' bastidores · '+t.blueprint.devices.length+' equipamentos'),`<button data-apply-template="${t.id}">Criar cópia</button><button data-delete-template="${t.id}" class="danger">Eliminar</button>`]));$('#newTemplate').onclick=()=>{form('Guardar modelo',input('name','Nome do modelo','Novo modelo','text','required')+select('source','Origem',[...p.sites.map(s=>({id:'sites:'+s.id,name:'Edifício · '+s.name})),...p.racks.map(r=>({id:'racks:'+r.id,name:'Bastidor · '+r.name}))],''),v=>{const [type,id]=v.source.split(':');app.mutate(p=>p.templates.push(templateFrom(p,type,id,v.name)));});};$('#studioBody').querySelectorAll('[data-delete-template]').forEach(b=>b.onclick=()=>{if(confirm('Eliminar este modelo? As cópias existentes são preservadas.'))act(()=>{app.mutate(p=>p.templates=p.templates.filter(t=>t.id!==b.dataset.deleteTemplate));renderTemplates();});});$('#studioBody').querySelectorAll('[data-apply-template]').forEach(b=>b.onclick=()=>{const t=p.templates.find(t=>t.id===b.dataset.applyTemplate);form('Criar a partir de '+t.name,input('name','Nome da cópia',t.name+' (cópia)','text','required')+(t.type==='racks'?select('siteId','Edifício de destino',p.sites,p.sites[0]?.id)+select('floorId','Piso de destino',p.floors.filter(f=>f.site===p.sites[0]?.id),null):'')+input('x',t.type==='sites'?'Posição X no campus':'Posição X dentro do edifício',t.type==='sites'?15:0,'number','step="0.1" required')+input('z',t.type==='sites'?'Posição Z no campus':'Posição Z dentro do edifício',t.type==='sites'?15:0,'number','step="0.1" required'),v=>app.mutate(p=>applyTemplate(p,t,v)),f=>{if(t.type==='racks')f.elements.siteId.onchange=()=>f.elements.floorId.innerHTML=opt(p.floors.filter(x=>x.site===f.elements.siteId.value),'');});});}
 function renderAudit(){const p=app.get().project,issues=auditProject(p);$('#studioBody').innerHTML=`<div class="studio-intro"><p>${issues.length} observações. Verificação documental de IPs, sub-redes, gateways, cabos, VLANs e ocupação de bastidores. Não substitui testes na rede real.</p><button id="refreshAudit">Verificar novamente</button></div>`+table(['Nível','Observação','Elemento'],issues.map(i=>[`<span class="issue-${i.severity}">${i.severity==='erro'?'Erro':'Aviso'}</span>`,e(i.message),`<button data-issue-type="${i.type}" data-issue-id="${i.id}">Abrir</button>`]));if(!issues.length)$('#studioBody').insertAdjacentHTML('beforeend','<p class="success-note">Não foram encontradas incongruências nas verificações disponíveis.</p>');$('#refreshAudit').onclick=renderAudit;$('#studioBody').querySelectorAll('[data-issue-id]').forEach(b=>b.onclick=()=>{if(b.dataset.issueType==='links')cableForm(b.dataset.issueId);else{$('#studio').close();app.select(b.dataset.issueType,b.dataset.issueId);}});}
 function renderSimulation(){const p=app.get().project;$('#studioBody').innerHTML=`<p class="notice">Simule a perda de ligação a um destino. O cálculo usa os cabos e canais de patch panels/tomadas documentados. Não emula protocolos, ACLs, serviços ou falhas de alimentação.</p><label class="form-field">Destino de referência<select id="simulationTarget">${opt(p.devices,simulation?.target||p.devices.find(d=>d.type==='Internet')?.id||p.devices[0]?.id)}</select></label><div class="failure-columns"><section><h3>Equipamentos desligados</h3>${p.devices.map(d=>`<label class="check-row"><input type="checkbox" data-fail-device="${d.id}" ${disabledDevices.includes(d.id)?'checked':''}>${e(d.name)}</label>`).join('')}</section><section><h3>Cabos desligados</h3>${p.links.filter(l=>l.kind!=='power').map(l=>`<label class="check-row"><input type="checkbox" data-fail-link="${l.id}" ${disabledLinks.includes(l.id)?'checked':''}>${e(l.label||l.id)}</label>`).join('')}</section></div><div class="studio-intro"><button id="runSimulation" class="primary">Simular</button><button id="resetSimulation">Repor todas as ligações</button></div><div id="simulationResult"></div>`;$('#runSimulation').onclick=()=>{const target=$('#simulationTarget').value;if(!target)return message('Adicione equipamentos ao projeto.',true);disabledDevices=[...$('#studioBody').querySelectorAll('[data-fail-device]:checked')].map(x=>x.dataset.failDevice);disabledLinks=[...$('#studioBody').querySelectorAll('[data-fail-link]:checked')].map(x=>x.dataset.failLink);simulation={target,...simulateFailure(p,target,disabledDevices,disabledLinks)};app.render();$('#simulationResult').innerHTML=`<h3>${simulation.lost.length} equipamentos perderiam conectividade</h3><p>${e(simulation.lost.map(id=>p.devices.find(d=>d.id===id)?.name).join(', ')||'Nenhum equipamento adicional afetado.')}</p><p class="notice">${simulation.already.length} já não tinham percurso documentado até ao destino.</p><button id="viewFailure">Ver no mapa</button>`;$('#viewFailure').onclick=()=>$('#studio').close();};$('#resetSimulation').onclick=()=>{disabledDevices=[];disabledLinks=[];simulation=null;app.render();renderSimulation();};}
 async function loadVersions(){try{message('A carregar versões…');const data=await api('/api/versions');versionList=data.versions||[];if(tab==='versions'){renderVersions();message('');}}catch(err){message(err.message,true);}}
 function renderVersions(){const p=app.get().project;$('#studioBody').innerHTML=`<div class="studio-intro"><p>Guarde marcos como «Rede atual» e «Expansão proposta». Compare qualquer versão com o projeto aberto ou com outra versão. Até 200 versões por conta.</p><button id="saveVersion" class="primary">Guardar versão nomeada</button></div>`+table(['Versão','Data','Ações'],versionList.map(v=>[e(v.label),e(new Date(v.created_at).toLocaleString('pt-PT')),`<button data-compare-version="${v.id}">Comparar com atual</button><button data-restore-version="${v.id}">Restaurar</button><button data-export-version="${v.id}">Exportar cifrado</button><button data-delete-version="${v.id}" class="danger">Eliminar</button>`]))+`<div class="compare-pickers"><select id="compareA">${opt(versionList.map(v=>({id:v.id,name:v.label})),null,'Escolher versão A')}</select><select id="compareB">${opt(versionList.map(v=>({id:v.id,name:v.label})),null,'Projeto atual')}</select><button id="compareVersions">Comparar</button></div><div id="comparison"></div>`;$('#saveVersion').onclick=()=>form('Guardar versão',input('label','Nome','Rede atual','text','required maxlength="100"'),async v=>{await post('/api/versions',{label:v.label,project:app.get().project});await loadVersions();});const compare=async(a,b)=>{try{message('A comparar…');const va=await api('/api/versions/'+a),vb=b?await api('/api/versions/'+b):{label:'Projeto atual',project:app.get().project};const differences=compareProjects(va.project,vb.project);comparison={a:va.label,b:vb.label,differences};$('#comparison').innerHTML=`<h3>${e(va.label)} → ${e(vb.label)} · ${differences.length} alterações</h3>`+table(['Grupo','Elemento','Alteração','Campos'],differences.map(d=>[e(d.group),e(d.name),e(d.change),e(d.fields)]));message('');}catch(err){message(err.message,true);}};$('#compareVersions').onclick=()=>{if($('#compareA').value)compare($('#compareA').value,$('#compareB').value);};$('#studioBody').querySelectorAll('[data-compare-version]').forEach(b=>b.onclick=()=>compare(b.dataset.compareVersion));$('#studioBody').querySelectorAll('[data-export-version]').forEach(b=>b.onclick=async()=>{try{const v=await api('/api/versions/'+b.dataset.exportVersion);await exportProtected(v.project);message('Versão exportada num ficheiro cifrado.');}catch(err){message(err.message,true);}});$('#studioBody').querySelectorAll('[data-restore-version]').forEach(b=>b.onclick=async()=>{if(!confirm('Restaurar esta versão? O projeto atual será guardado numa versão de segurança antes da substituição.'))return;try{const v=await api('/api/versions/'+b.dataset.restoreVersion);await post('/api/versions',{label:'Antes de restaurar · '+new Date().toLocaleString('pt-PT'),project:app.get().project});app.replace(normalizeProject(v.project));await loadVersions();message('Versão restaurada. A cópia anterior foi preservada.');}catch(err){message(err.message,true);}});$('#studioBody').querySelectorAll('[data-delete-version]').forEach(b=>b.onclick=async()=>{if(!confirm('Eliminar definitivamente esta versão guardada?'))return;try{await api('/api/versions/'+b.dataset.deleteVersion,{method:'DELETE'});await loadVersions();}catch(err){message(err.message,true);}});}
 function renderDossier(){$('#studioBody').innerHTML=`<div class="dossier-intro"><h3>Dossier técnico da infraestrutura</h3><p class="export-warning">Estes formatos são legíveis e não cifrados. Para guardar uma cópia protegida do projeto, use Projeto → Exportar cifrado.</p><p>Gera um documento com plantas, pisos e salas, inventário, endereçamento, ocupação em U, mapa de cabos e portas, e observações da verificação.</p><ul><li>HTML autónomo para guardar e consultar.</li><li>Impressão / PDF com tabelas e plantas por piso.</li><li>CSV do inventário e das ligações para tratamento em folha de cálculo.</li></ul><div class="dossier-buttons"><button id="downloadDossier" class="primary">Descarregar dossier HTML</button><button id="printDossier">Imprimir / PDF</button><button id="csvDevices">Inventário CSV</button><button id="csvLinks">Ligações CSV</button></div><p class="notice">As plantas são esquemáticas. A escala de uma imagem importada depende da calibração fornecida.</p></div>`;$('#downloadDossier').onclick=()=>createDossier(false);$('#printDossier').onclick=()=>createDossier(true);$('#csvDevices').onclick=()=>{const p=app.get().project;csv('inventario',['Nome','Tipo','IP','VLAN','Gateway','Edifício','Piso','Sala','Bastidor','U inicial','Altura U'],p.devices.map(d=>[d.name,d.type,d.ip,d.vlan,d.gateway,p.sites.find(s=>s.id===d.site)?.name,p.floors.find(f=>f.id===d.floor)?.name,p.rooms.find(r=>r.id===d.room)?.name,p.racks.find(r=>r.id===d.rack)?.name,d.rack?d.u:'',d.rack?d.units:'']));};$('#csvLinks').onclick=()=>{const p=app.get().project;csv('ligacoes',['Cabo','Equipamento A','Porta A','Equipamento B','Porta B','Meio','Categoria','Comprimento m','VLANs','Percurso'],p.links.map(l=>[l.label,p.devices.find(d=>d.id===l.a)?.name,l.portA,p.devices.find(d=>d.id===l.b)?.name,l.portB,l.kind,l.category,l.length,l.vlans.join(','),l.routeNote]));};}
 function csv(name,headers,rows){if(!allowReadableExport())return;const safe=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};downloadFile(new Blob(['\uFEFF'+[headers,...rows].map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'atlas-'+name+'.csv');}
 async function dossierHTML(){const p=clone(app.get().project);for(const f of p.floors.filter(f=>f.plan)){const loaded=await imageData(f.plan.asset);if(!loaded)throw new Error('A planta de '+f.name+' não pôde ser carregada. Volte a tentar antes de gerar o dossier.');}const rows=(headers,data)=>table(headers,data.map(r=>r.map(v=>e(v??'—'))));let body=`<header><h1>${e(p.name)}</h1><p>Dossier técnico de infraestruturas informáticas · ${e(new Date().toLocaleString('pt-PT'))}</p><p>${p.sites.length} edifícios · ${p.floors.length} pisos · ${p.racks.length} bastidores · ${p.devices.length} equipamentos · ${p.links.length} ligações</p></header>${planSheetsHTML(p,{imageData:planImages})}`;
 body+=`<section><h2>Inventário e endereçamento</h2>${rows(['Equipamento','Tipo','IP','VLAN','Gateway','Edifício / Piso','Sala'],p.devices.map(d=>[d.name,d.type,d.ip,d.vlan,d.gateway||p.nets.find(n=>n.id===d.vlan)?.gateway,p.sites.find(s=>s.id===d.site)?.name+' / '+(p.floors.find(f=>f.id===d.floor)?.name||''),p.rooms.find(r=>r.id===d.room)?.name]))}<h2>Redes</h2>${rows(['VLAN','Nome','Sub-rede','Gateway'],p.nets.map(n=>[n.id,n.name,n.subnet,n.gateway]))}</section>`;
 for(const r of p.racks)body+=`<section><h2>${e(r.name)} · ${r.units} U</h2>${rows(['U inicial','U final','Equipamento','Tipo','IP'],p.devices.filter(d=>d.rack===r.id).sort((a,b)=>b.u-a.u).map(d=>[d.u,d.u+d.units-1,d.name,d.type,d.ip]))}</section>`;
 for(const d of p.devices.filter(d=>d.type==='PDU'))body+='<section><h2>Régua elétrica · '+e(d.name)+'</h2>'+rows(['Tomada','Etiqueta','Equipamento','Entrada / fonte','Cabo'],pduOutlets(p,d).map(o=>[o.number,o.label,o.device?.name||'Livre',o.input,o.link?.label||'']))+'</section>';
 body+=`<section><h2>Mapa de cabos e portas</h2>${rows(['Cabo','A / porta','B / porta','Tipo','m','VLANs','Percurso'],p.links.map(l=>[l.label,(p.devices.find(d=>d.id===l.a)?.name||'')+' / '+l.portA,(p.devices.find(d=>d.id===l.b)?.name||'')+' / '+l.portB,l.category||l.kind,l.length,l.vlans.join(', '),l.routeNote]))}</section><section><h2>Verificação documental</h2>${rows(['Nível','Observação'],auditProject(p).map(i=>[i.severity,i.message]))}<p>Este dossier documenta o modelo configurado. Não certifica instalações nem confirma o estado real dos equipamentos.</p></section>`;
 return `<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><title>${e(p.name)} — Dossier técnico</title><style>${planPrintStyles}body{font:14px Arial,sans-serif;color:#172f40;background:white;margin:24px}h1{font-size:30px}h2{font-size:20px;margin-top:30px}table{width:100%;border-collapse:collapse;margin:15px 0;font-size:11px}th,td{border:1px solid #b8c5cc;padding:7px;text-align:left;overflow-wrap:anywhere}th{background:#eaf0f4}svg{width:100%;height:auto;max-height:85vh}section{margin:25px 0}header{border-bottom:3px solid #197e71;padding-bottom:15px}.studio-table{overflow:visible}@media print{@page{size:A3 landscape;margin:12mm}body{margin:0}.atlas-print-sheet{height:259mm;break-before:page;margin:0}.atlas-print-drawing>svg{max-height:none}svg{max-height:250mm}tr{break-inside:avoid}thead{display:table-header-group}h2{break-after:avoid}section{break-inside:auto}}</style></head><body>${body}</body></html>`;
 }
